-- PT117-S4-Q23. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT117-S4-Q23$batch13$ AND q.stimulus=$batch13$Political scientist: One of the most interesting dilemmas in contemporary democratic politics concerns the regulation of political campaign spending. People certainly should be free, within broad limits, to spend their money as they choose. On the other hand, candidates who can vastly outspend all rivals have an unfair advantage in publicizing their platforms. Democratic governments have a strong obligation to ensure that all voices have an equal chance to be heard, but governments should not subsidize expensive campaigns for each candidate. The resolution of the dilemma, therefore, is clear: _______.$batch13$ AND q.prompt=$batch13$Which one of the following most logically completes the political scientist's argument?$batch13$ AND q.correct_choice=$batch13$B$batch13$) THEN RAISE EXCEPTION 'Question changed: PT117-S4-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT117-S4-Q23$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S4-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT117-S4-Q23$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Statements$batch13$, $batch13$People should be free, within broad limits, to spend their money. Candidates who vastly outspend rivals have an unfair advantage. Governments must give every voice an equal chance to be heard. Governments should not subsidize expensive campaigns for each candidate.$batch13$), (1, $batch13$Evaluate$batch13$, $batch13$The answer has to fit every constraint. It must curb outspending but leave people broadly free to spend, and it can't use subsidies. A cap on each candidate's spending does all three.$batch13$), (2, $batch13$Goal$batch13$, $batch13$Limit how much any candidate can spend.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT117-S4-Q23$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Letting only well-funded candidates run makes the unfair advantage worse.$batch13$), ($batch13$B$batch13$, $batch13$A cap stops anyone from vastly outspending rivals, leaves room to spend within it, and needs no subsidy.$batch13$), ($batch13$C$batch13$, $batch13$The scientist says governments shouldn't subsidize campaigns.$batch13$), ($batch13$D$batch13$, $batch13$Banning wealthy people from spending their own money goes beyond "broad limits" on freedom.$batch13$), ($batch13$E$batch13$, $batch13$This is the most popular trap. Letting each candidate match any rival's spending caps nothing. Candidates who can afford to outspend still win the advantage.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT117-S4-Q23$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
